1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="color-scheme" content="light dark">
7	  <title>Animated Circle - Interactive Demo</title>
8	  <meta name="description" content="A responsive, accessible circle that changes color when clicked">
9	  <meta name="theme-color" content="#ffffff" media="(prefers-color-scheme: light)">
10	  <meta name="theme-color" content="#111111" media="(prefers-color-scheme: dark)">
11	  <link rel="icon" href="data:,">
12	  <style>
13	    *,
14	    *::before,
15	    *::after {
16	      box-sizing: border-box;
17	      margin: 0;
18	      padding: 0;
19	    }
20	    :root {
21	      color-scheme: light dark;
22	      --bg: #fff;
23	      --text: #374151;
24	      --fg: #2563eb;
25	      --shadow: rgba(0, 0, 0, 0.1);
26	      --kbd-bg: rgba(0, 0, 0, 0.1);
27	      --drop: drop-shadow(0 4px 12px var(--shadow));
28	    }
29	    [data-color="red"] { --fg: #dc2626; }
30	    /* Dark enough to keep 3:1 against --bg at the resting 0.85 opacity */
31	    [data-color="green"] { --fg: #15803d; }
32	    [data-color="amber"] { --fg: #b45309; }
33	    [data-color="violet"] { --fg: #7c3aed; }
34	    [data-color="cyan"] { --fg: #0e7490; }
35	    @media (prefers-color-scheme: dark) {
36	      :root {
37	        --bg: #111;
38	        --text: #d1d5db;
39	        --fg: #93c5fd;
40	        --shadow: rgba(0, 0, 0, 0.6);
41	        --kbd-bg: rgba(255, 255, 255, 0.15);
42	      }
43	      [data-color="red"] { --fg: #fca5a5; }
44	      [data-color="green"] { --fg: #86efac; }
45	      [data-color="amber"] { --fg: #fcd34d; }
46	      [data-color="violet"] { --fg: #c4b5fd; }
47	      [data-color="cyan"] { --fg: #67e8f9; }
48	    }
49	    @media (prefers-contrast: more) {
50	      :root {
51	        --shadow: rgba(0, 0, 0, 0.9);
52	        --drop: drop-shadow(0 2px 8px var(--shadow));
53	      }
54	      .circle svg {
55	        opacity: 1;
56	      }
57	    }
58	    @media (forced-colors: active) {
59	      svg circle {
60	        stroke: CanvasText;
61	        stroke-width: 2;
62	      }
63	    }
64	    body {
65	      min-height: 100vh;
66	      min-height: 100dvh;
67	      display: grid;
68	      place-items: center;
69	      padding: 1rem;
70	      background: var(--bg);
71	      color: var(--text);
72	      font-family: system-ui, -apple-system, sans-serif;
73	    }
74	    main {
75	      width: 100%;
76	      display: flex;
77	      flex-direction: column;
78	      align-items: center;
79	      text-align: center;
80	    }
81	    .circle {
82	      display: block;
83	      width: min(360px, 100%, 60vh);
84	      aspect-ratio: 1;
85	      border: 0;
86	      border-radius: 50%;
87	      background: none;
88	      color: var(--fg);
89	      cursor: pointer;
90	      touch-action: manipulation;
91	      -webkit-tap-highlight-color: transparent;
92	      /* Shift+click and double-click would otherwise select the text below */
93	      -webkit-user-select: none;
94	      user-select: none;
95	      transition: color 0.4s ease;
96	      min-height: 48px;
97	      min-width: 48px;
98	    }
99	    .no-transition,
100	    .no-transition svg {
101	      transition: none !important;
102	    }
103	    .circle:focus-visible {
104	      outline: 3px solid currentColor;
105	      outline-offset: 12px;
106	    }
107	    svg {
108	      display: block;
109	      width: 100%;
110	      height: 100%;
111	      overflow: visible;
112	      opacity: 0.85;
113	      filter: var(--drop);
114	      transition: opacity 0.3s ease;
115	    }
116	    .circle:active svg,
117	    .circle:focus-visible svg {
118	      opacity: 1;
119	    }
120	    @keyframes pulse {
121	      0% {
122	        filter: var(--drop) drop-shadow(0 0 16px currentColor);
123	      }
124	      100% {
125	        filter: var(--drop) drop-shadow(0 0 0 transparent);
126	      }
127	    }
128	    @media (hover: hover) {
129	      .circle:hover svg {
130	        opacity: 1;
131	      }
132	    }
133	    @media (prefers-reduced-motion: no-preference) {
134	      svg {
135	        transition:
136	          transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1),
137	          opacity 0.3s ease;
138	      }
139	      .circle:focus-visible svg {
140	        transform: scale(1.05);
141	      }
142	      .circle:active svg {
143	        transform: scale(0.97);
144	      }
145	      .circle.color-changed svg {
146	        animation: pulse 0.5s ease-out;
147	      }
148	    }
149	    @media (hover: hover) and (prefers-reduced-motion: no-preference) {
150	      .circle:hover:not(:active) svg {
151	        transform: scale(1.05);
152	      }
153	    }
154	    .visually-hidden {
155	      position: absolute;
156	      width: 1px;
157	      height: 1px;
158	      overflow: hidden;
159	      clip-path: inset(50%);
160	      white-space: nowrap;
161	    }
162	    .status {
163	      margin-top: 2rem;
164	      font-weight: 600;
165	    }
166	    .hint {
167	      margin-top: 0.25rem;
168	      font-size: 0.875rem;
169	      line-height: 1.75;
170	      text-wrap: balance;
171	    }
172	    .help-button {
173	      margin-left: 0.5rem;
174	      display: inline-block;
175	      width: 1.5rem;
176	      height: 1.5rem;
177	      border-radius: 50%;
178	      background: var(--kbd-bg);
179	      border: 1px solid var(--text);
180	      color: var(--text);
181	      cursor: pointer;
182	      font: inherit;
183	      font-size: 0.75rem;
184	      font-weight: bold;
185	      line-height: 1;
186	      text-align: center;
187	      vertical-align: middle;
188	      touch-action: manipulation;
189	      transition: background-color 0.2s ease, color 0.2s ease;
190	    }
191	    .help-button:focus-visible {
192	      outline: 2px solid currentColor;
193	      outline-offset: 2px;
194	    }
195	    @media (hover: hover) {
196	      /* Not currentColor: it would resolve to the hover color and hide the "?" */
197	      .help-button:hover {
198	        background: var(--text);
199	        color: var(--bg);
200	      }
201	    }
202	    .keys {
203	      display: none;
204	    }
205	    .keys.visible {
206	      display: inline;
207	    }
208	    @media (hover: none) and (pointer: coarse) {
209	      .hint .keys {
210	        display: none !important;
211	      }
212	      .help-button {
213	        display: none;
214	      }
215	    }
216	    kbd {
217	      display: inline-block;
218	      padding: 0.125rem 0.375rem;
219	      background: var(--kbd-bg);
220	      border: 1px solid transparent;
221	      border-radius: 0.25rem;
222	      font-family: monospace;
223	      font-size: 0.75em;
224	      line-height: 1.2;
225	    }
226	  </style>
227	</head>
228	<body>
229	  <main>
230	    <h1 class="visually-hidden">Animated Circle</h1>
231	    <button type="button" class="circle no-transition" aria-label="Change circle color" aria-describedby="status hint">
232	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
233	        <circle cx="50" cy="50" r="50" fill="currentColor" stroke="none"/>
234	      </svg>
235	    </button>
236	    <p class="status" id="status" role="status">Blue</p>
237	    <p class="hint"><span id="hint"><span class="verb">Click</span> to cycle • <span class="double-verb">Double-click</span> or hold to reset<span class="keys" id="keys"> • <kbd>Shift</kbd>+click reverse • <kbd>↑↓←→</kbd> navigate • <kbd>Home</kbd>/<kbd>End</kbd> jump</span></span> <button type="button" class="help-button" aria-label="Keyboard shortcuts" aria-expanded="false" aria-controls="keys"><span aria-hidden="true">?</span></button></p>
238	    <noscript><p class="hint">JavaScript is required to change the color.</p></noscript>
239	  </main>
240	  <script>
241	    const config = {
242	      colors: ['blue', 'red', 'green', 'amber', 'violet', 'cyan'],
243	      storageKey: 'circle-color',
244	      hapticDuration: 50,
245	      keySteps: { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 },
246	    };
247	
248	    const DOM = {
249	      button: document.querySelector('.circle'),
250	      status: document.querySelector('.status'),
251	      helpButton: document.querySelector('.help-button'),
252	      keyHint: document.querySelector('.keys'),
253	      verbSpan: document.querySelector('.hint .verb'),
254	      doubleVerbSpan: document.querySelector('.hint .double-verb'),
255	    };
256	
257	    const state = {
258	      index: 0,
259	      shiftHeld: false,
260	      hoverCapable: true,
261	      reducedMotion: matchMedia('(prefers-reduced-motion: reduce)'),
262	      hoverQuery: matchMedia('(hover: none)'),
263	      longPressTimer: null,
264	      pointerDownTime: 0,
265	    };
266	
267	    function loadColor() {
268	      try {
269	        return localStorage.getItem(config.storageKey);
270	      } catch {
271	        return null;
272	      }
273	    }
274	
275	    function saveColor(color) {
276	      try {
277	        localStorage.setItem(config.storageKey, color);
278	      } catch {}
279	    }
280	
281	    function applyColor() {
282	      const color = config.colors[state.index];
283	      DOM.button.dataset.color = color === 'blue' ? '' : color;
284	      DOM.status.textContent = color[0].toUpperCase() + color.slice(1);
285	    }
286	
287	    function syncFromStorage(color = loadColor()) {
288	      const index = config.colors.indexOf(color);
289	      state.index = index === -1 ? 0 : index;
290	      applyColor();
291	    }
292	
293	    function setIndex(next, { haptic = false } = {}) {
294	      if (next === state.index) return;
295	      state.index = next;
296	      applyColor();
297	      saveColor(config.colors[state.index]);
298	
299	      if (haptic && navigator.vibrate) navigator.vibrate(config.hapticDuration);
300	
301	      if (state.reducedMotion.matches) return;
302	      DOM.button.classList.remove('color-changed');
303	      void DOM.button.offsetWidth;
304	      DOM.button.classList.add('color-changed');
305	    }
306	
307	    function changeColor(step) {
308	      setIndex((state.index + step + config.colors.length) % config.colors.length, { haptic: true });
309	    }
310	
311	    function updateDeviceVerbs() {
312	      state.hoverCapable = !state.hoverQuery.matches;
313	      DOM.verbSpan.textContent = state.hoverCapable ? 'Click' : 'Tap';
314	      DOM.doubleVerbSpan.textContent = state.hoverCapable ? 'Double-click' : 'Double-tap';
315	    }
316	
317	    function toggleKeyHintVisibility() {
318	      const expanded = DOM.keyHint.classList.toggle('visible');
319	      DOM.helpButton.setAttribute('aria-expanded', expanded);
320	    }
321	
322	    function syncKeyHint() {
323	      DOM.keyHint.classList.toggle('visible', state.hoverCapable);
324	      DOM.helpButton.setAttribute('aria-expanded', state.hoverCapable);
325	    }
326	
327	    function handleKeyDown(event) {
328	      if (event.key === 'Enter' || event.key === ' ') {
329	        if (!event.repeat) state.shiftHeld = event.shiftKey;
330	        if (event.key === 'Enter' && event.repeat) event.preventDefault();
331	        return;
332	      }
333	
334	      if (event.altKey || event.ctrlKey || event.metaKey) return;
335	
336	      if (event.key in config.keySteps) {
337	        event.preventDefault();
338	        changeColor(config.keySteps[event.key]);
339	      } else if (event.key === 'Home') {
340	        event.preventDefault();
341	        setIndex(0, { haptic: true });
342	      } else if (event.key === 'End') {
343	        event.preventDefault();
344	        setIndex(config.colors.length - 1, { haptic: true });
345	      }
346	    }
347	
348	    // Initialize
349	    syncFromStorage();
350	
351	    requestAnimationFrame(() => requestAnimationFrame(() => {
352	      DOM.button.classList.remove('no-transition');
353	    }));
354	
355	    updateDeviceVerbs();
356	    syncKeyHint();
357	    // e.g. a tablet gaining or losing a trackpad/keyboard
358	    state.hoverQuery.addEventListener('change', () => {
359	      updateDeviceVerbs();
360	      syncKeyHint();
361	    });
362	
363	    // Event listeners
364	    function clearLongPressTimer() {
365	      if (state.longPressTimer) clearTimeout(state.longPressTimer);
366	      state.longPressTimer = null;
367	    }
368	
369	    DOM.button.addEventListener('keydown', handleKeyDown);
370	    DOM.button.addEventListener('keyup', (event) => {
371	      if (event.key === ' ') state.shiftHeld = event.shiftKey;
372	    });
373	    DOM.button.addEventListener('blur', () => {
374	      state.shiftHeld = false;
375	      clearLongPressTimer();
376	    });
377	    DOM.button.addEventListener('pointerdown', (event) => {
378	      state.pointerDownTime = event.timeStamp;
379	      clearLongPressTimer();
380	      state.longPressTimer = setTimeout(() => {
381	        setIndex(0, { haptic: true });
382	      }, 500);
383	    });
384	    DOM.button.addEventListener('pointerup', clearLongPressTimer);
385	    DOM.button.addEventListener('pointercancel', clearLongPressTimer);
386	    DOM.button.addEventListener('click', (event) => {
387	      clearLongPressTimer();
388	      if (event.detail > 1) return;
389	      changeColor(event.shiftKey || state.shiftHeld ? -1 : 1);
390	      state.shiftHeld = false;
391	    });
392	    DOM.button.addEventListener('dblclick', (event) => {
393	      event.preventDefault();
394	      setIndex(0);
395	    });
396	    DOM.button.addEventListener('animationend', () => {
397	      DOM.button.classList.remove('color-changed');
398	    });
399	
400	    DOM.helpButton.addEventListener('click', toggleKeyHintVisibility);
401	
402	    addEventListener('storage', (event) => {
403	      if (event.key !== config.storageKey && event.key !== null) return;
404	      syncFromStorage(event.newValue);
405	    });
406	    // Storage events are not delivered while the page sits in the bfcache
407	    addEventListener('pageshow', (event) => {
408	      if (event.persisted) syncFromStorage();
409	    });
410	  </script>
411	</body>
412	</html>
