DOM.button.addEventListener('pointerdown', (event) => {
  clearLongPressTimer();
  state.longPressed = false;
  if (!event.isPrimary || event.button !== 0) return;
  state.longPressTimer = setTimeout(() => {
    state.longPressTimer = null;
    state.longPressed = true;
    setIndex(0, { haptic: true });
  }, config.longPressDuration);
});
DOM.button.addEventListener('pointerup', clearLongPressTimer);
DOM.button.addEventListener('pointercancel', clearLongPressTimer);
DOM.button.addEventListener('pointerleave', clearLongPressTimer);
DOM.button.addEventListener('click', (event) => {
  clearLongPressTimer();
  // Releasing a long press still fires a click, which would undo the reset.
  // Keyboard clicks (detail 0) are never part of a long press.
  const afterLongPress = state.longPressed && event.detail !== 0;
  state.longPressed = false;
  if (afterLongPress || event.detail > 1) return;

